import { createRequire } from 'node:module';
import { expect } from 'chai';
import { decode, DXNError, DXNKeyword, DXNList } from '../../src/dextrin.js';
import { InvalidData, Runtime } from '../../src/codegen-runtime.js';

const require = createRequire(import.meta.url);
const cjs = require('../../src/codegen-runtime.cjs');
const TypeExpr = require('../../src/schema/type-expr.cjs');

/*
 * `@joetjen/dextrin/codegen-runtime`, what code generated by `dextrin
 * gen-js` calls: InvalidData, and one helper per form a check takes.
 */
describe('codegen runtime (@joetjen/dextrin/codegen-runtime)', () => {
  it('CJS entry point matches the ESM one (dual entry-point parity)', () => {
    expect(cjs.InvalidData).to.equal(InvalidData);
    expect(cjs.Runtime).to.equal(Runtime);
    expect(Object.keys(cjs).sort()).to.deep.equal(['InvalidData', 'Runtime']);
  });

  it('is exported by the package as @joetjen/dextrin/codegen-runtime', async () => {
    const pkg = require('../../package.json');
    expect(pkg.exports['./codegen-runtime'].import.default).to.equal('./src/codegen-runtime.js');
    expect(pkg.exports['./codegen-runtime'].require.default).to.equal('./src/codegen-runtime.cjs');
    const self = await import('@joetjen/dextrin/codegen-runtime');
    expect(self.InvalidData).to.equal(InvalidData);
  });

  describe('InvalidData', () => {
    it('is a DXNError at stage schema naming the field, outermost first', () => {
      const err = new InvalidData('expected string, got 1').under('label').under('[0]').under('children').under('tree');
      expect(err).to.be.instanceOf(DXNError);
      expect(err.name).to.equal('InvalidData');
      expect(err.stage).to.equal('schema');
      expect(err.path).to.deep.equal(['tree', 'children', '[0]', 'label']);
      expect(err.reason).to.equal('expected string, got 1');
      expect(err.message).to.equal('tree.children[0].label: expected string, got 1');
      expect(err.category).to.equal('schema/type-mismatch');
    });

    it('keeps its category one field further out', () => {
      expect(new InvalidData('missing required field a', [], 'schema/missing-field').under('x').category).to.equal('schema/missing-field');
    });

    it('expected() shows the value as DXN', () => {
      expect(InvalidData.expected('a list', decode('%{a: 1}')).message).to.equal('expected a list, got %{a:1}');
    });
  });

  describe('the narrow checks generated code calls', () => {
    it('isPrimitive', () => {
      expect(TypeExpr.isPrimitive('integer', 1n)).to.equal(true);
      expect(TypeExpr.isPrimitive('integer', 1)).to.equal(false);
      expect(TypeExpr.isPrimitive('keyword', Symbol.for('a'))).to.equal(true);
    });

    it('isEnumMember takes a keyword as a DXNKeyword or a global symbol', () => {
      const literals = [new DXNKeyword('open'), 'x'];
      expect(TypeExpr.isEnumMember(literals, new DXNKeyword('open'))).to.equal(true);
      expect(TypeExpr.isEnumMember(literals, Symbol.for('open'))).to.equal(true);
      expect(TypeExpr.isEnumMember(literals, 'y')).to.equal(false);
    });

    it('meetsConstraints, a length counted as the refined primitive says', () => {
      expect(TypeExpr.meetsConstraints('ab', { 'min-length': 2n }, 'string')).to.equal(true);
      expect(TypeExpr.meetsConstraints('a', { 'min-length': 2n }, 'string')).to.equal(false);
      expect(TypeExpr.meetsConstraints(5n, { max: 9n }, null)).to.equal(true);
    });
  });

  describe('Runtime', () => {
    it('fields() checks what is declared, fills defaults, and refuses what is missing', () => {
      const string = (/** @type {unknown} */ v) => {
        if (typeof v !== 'string') throw InvalidData.expected('string', v);
        return v;
      };
      const out = Runtime.fields({ a: 'x', z: 1 }, [
        ['a', true, string, null],
        ['b', true, string, () => 'B'],
        ['c', false, string, null]
      ]);
      expect({ ...out }).to.deep.equal({ a: 'x', b: 'B' });
      expect(() => Runtime.fields({ a: 1 }, [['a', true, string, null]])).to.throw(InvalidData, 'a: expected string, got 1');
      expect(() => Runtime.fields({}, [['a', true, string, null]])).to.throw(InvalidData, 'missing required field a');
    });

    it('listOf() answers a new list, an item refused as [n]', () => {
      const list = /** @type {DXNList} */ (Runtime.listOf(decode('[1 2]'), (v) => v));
      expect(list).to.be.instanceOf(DXNList);
      expect(() => Runtime.listOf(decode('[1 "a"]'), (v) => {
        if (typeof v !== 'bigint') throw InvalidData.expected('integer', v);
        return v;
      })).to.throw(InvalidData, '[1]: expected integer, got "a"');
    });

    it('a field bag has no prototype to write through', () => {
      const fields = Runtime.named(decode('%a/B{__proto__: 1}'), ['__proto__']);
      expect(Object.getPrototypeOf(fields)).to.equal(null);
      expect(fields.__proto__).to.equal(1n);
    });
  });
});
